function addModelInfoBox() { setTimeout(() => { const modelInfo = document.querySelector('[data-model-info]'); const targetImg = document.querySelector('img[data-nimg]'); if (!modelInfo || !targetImg) return; const parent = targetImg.closest('span'); if (!parent || parent.querySelector('.model-sizing-wrapper')) return; parent.style.position = 'relative'; const wrapper = document.createElement('div'); wrapper.className = 'model-sizing-wrapper'; wrapper.style.cssText = ` position: absolute; bottom: 10px; left: 10px; z-index: 20; font-size: .875rem; font-family: sans-serif; `; const button = document.createElement('div'); button.textContent = 'Wymiary'; button.style.cssText = ` backdrop-filter: blur(24px); background-color: hsla(0,0%,100%,.75); color: black; padding: 5px 9px; border-radius: 4px; cursor: pointer; display: inline-block; touch-action: manipulation; `; const infoBox = document.createElement('div'); infoBox.style.cssText = ` backdrop-filter: blur(24px); display: none; background-color: hsla(0,0%,100%,.75); color: black; margin-top: 5px; padding: 10px; border-radius: 8px; line-height: 1.4; white-space: normal; width: calc(100% + 20px); max-width: unset; `; const lines = modelInfo.innerHTML.split(/<br\s*\/?>/i); lines.forEach((lineHtml, index) => { const lineDiv = document.createElement('div'); lineDiv.innerHTML = lineHtml.trim(); if (index === 1) { lineDiv.style.marginTop = '12px'; } lineDiv.style.marginBottom = '4px'; infoBox.appendChild(lineDiv); }); const isMobile = window.matchMedia('(hover: none) and (pointer: coarse)').matches; if (!isMobile) { wrapper.addEventListener('mouseenter', () => { infoBox.style.display = 'block'; }); wrapper.addEventListener('mouseleave', () => { infoBox.style.display = 'none'; }); } else { let visible = false; button.addEventListener('click', (e) => { e.stopPropagation(); visible = !visible; infoBox.style.display = visible ? 'block' : 'none'; }); document.addEventListener('click', (e) => { if (!wrapper.contains(e.target)) { infoBox.style.display = 'none'; visible = false; } }); } wrapper.appendChild(button); wrapper.appendChild(infoBox); parent.appendChild(wrapper); }, 100);}

function addReturnsInfo() {
    setTimeout(() => {
        const targetImg = document.querySelector('img[data-nimg]');
        if (targetImg) {
            const parent = targetImg.closest('span');
            if (parent && !parent.querySelector('.returns-info')) {
                parent.style.position = 'relative';

                const link = Object.assign(document.createElement('a'), {
                    href: '/zwroty',
                    className: 'returns-info',
                    style: 'position: absolute; top: 10px; z-index: 10;',
                    target: '_blank'
                });

                const icoInfo = Object.assign(document.createElement('img'), {
                    src: 'https://newbalance.pl/picture/files/upload/icon/zwrot-30-dni-min.png',
                    alt: '30 dni na darmowy zwrot x',
                    width:  65,
                    height:  90,
                    style: 'height: 90px; pointer-events: none;'
                });

                link.appendChild(icoInfo);
                parent.insertBefore(link, targetImg);

                const updatePosition = () => {
                    link.style.cssText += window.innerWidth <= 1023
                        ? 'right: 10px; left: auto;'
                        : 'left: 10px; right: auto;';
                };

                updatePosition();
                window.addEventListener('resize', updatePosition);
            }
        }
    }, 50);
}


if (!document.querySelector(".returns-info")) {
	addReturnsInfo();
addModelInfoBox();
	var targetSelector = "h1[data-qa-product_name]";

	let targetNode = document.querySelector(targetSelector);

	// Sprawdź, czy element istnieje
	if (targetNode) {
		// Opcje dla obserwatora
		const config = {
			attributes: true,
			childList: true,
			characterData: true,
		};

		const observer = new MutationObserver(function (mutations) {
			mutations.forEach(function (mutation) {
				// Wykryto zmianę, wywołaj funkcję
				addReturnsInfo();
addModelInfoBox();
ProductParameterModule.init();
createGenderToggle();
			});
		});

		observer.observe(targetNode, config);
	} else {
		console.warn(`Element ${targetSelector} nie znaleziony.`);
	}
}
</script>
<style>
li[data-profile-symbol="feed_gender"], li[data-profile-symbol="material"], li[data-profile-symbol="h1_title"], li[data-profile-symbol="run_headline"],
li[data-profile-symbol="cushioning"], li[data-profile-symbol="technology"], li[data-profile-symbol="purpose"], li[data-profile-symbol="weight"],  li[data-profile-symbol="related_gender_version"] {
  display: none;
}
.gcode-runparam {
            width: 100%;
            background: transparent;
            border: none;
            margin-top: 20px;
        }

        .param-header {
            background-color: #f2f2f2;
            padding: 15px 18px;
            text-align: center;
            font-weight: 600;
            font-size: 15px;
            color: #333;
            border-bottom: none;
            border-radius: 4px;
        }

        .param-subheader {
            background-color: #f2f2f2;
            padding: 10px 18px 10px 18px;
            text-align: center;
            font-size: 13px;
            color: #666;
            border-bottom: none;
            border-radius: 4px;
        }

        .param-subheader .category {
            font-weight: 600;
            color: #000;
            display: block;
            margin-top: 2px;
            font-size: 13px;
        }

        .param-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 6px;
            border-top: none;
        }

        .param-grid.two-columns {
            grid-template-columns: 1fr 1fr;
        }

        .param-grid.two-columns .param-item.full-width,
        .param-grid.two-columns .param-header.full-width,
        .param-grid.two-columns .param-subheader.full-width {
            grid-column: 1 / -1;
        }

        .param-item.half-width {
            grid-column: span 1;
        }

        .param-item {
