            gap: 6px;
            font-weight: 400;
        }

        .param-item.half-width .param-label {
            justify-content: flex-start;
        }

        .param-value {
            font-size: 16px;
            font-weight: 600;
            color: #000;
            line-height: 1.3;
        }

        .info-icon {
            width: 14px;
